&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;VML is seeking a&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;Data &amp;amp; Analytics Partner&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;to&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;lead the setup&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;&amp;nbsp;and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;onboarding&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;of a&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;new client.&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;&amp;nbsp;You will be a trusted partner to our client, navigating their business, understanding their&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;challenges&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;&amp;nbsp;and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;connecting across VML&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;&amp;nbsp;as well as WPP at large&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;&amp;nbsp;to&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;ensure&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;we are setup to&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;deliver&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;success with&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;world-class services and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;solutions&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;[Basic Paragraph]&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:57,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
