&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;49&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body List&quot;&gt;Diagnose and tune performance across the interconnect stack, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body List&quot;&gt;from application&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body List&quot;&gt; collective communication down to link level, working with technologies including &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body List&quot;&gt;NVLink&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body List&quot;&gt;, InfiniBand, RoCE and congestion control tuning.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
