&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;En tant que membre de l’équipe de management du site, vous veillerez à assurer une couverture opérationnelle adaptée, à garantir la continuité des activités et à fournir des services fiables aux clients internes et externes. Vous collaborerez étroitement avec les ingénieurs, chefs de projet, équipes en charge des environnements critiques, fournisseurs et partenaires internes, tout en développant une équipe performante et en contribuant à l’amélioration continue des opérations du centre de données.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Votre&amp;nbsp;expérience&amp;nbsp;doit&amp;nbsp;inclure&amp;nbsp;...&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience confirmée en management et leadership d’équipes en charge des opérations techniques, dans un centre de données, une infrastructure ou un environnement&amp;nbsp;stratégique.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans le support de clients Enterprise et de services stratégiques pour l’entreprise, dans un environnement opérationnel.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Connaissances techniques dans au moins deux des domaines suivants : administration système (Linux et/ou Windows), réseaux, architecture des centres de données ou programmation/scripting.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans la délégation des tâches, la gestion de la charge de travail, la formation et le développement des membres de l’équipe.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans la coordination de projets opérationnels, l’amélioration des processus ainsi que la gestion de la documentation et du&amp;nbsp;reporting&amp;nbsp;opérationnels.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;br&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Idéalement, vous disposez également de…&amp;nbsp;..&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience de 3 ans ou plus dans un centre de données, dans un rôle comportant des responsabilités d’encadrement, de supervision ou de management.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Bonne connaissance des systèmes d’exploitation Linux et Windows.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience avec Python, Bash, PowerShell, Java ou d’autres technologies de&amp;nbsp;scripting&amp;nbsp;et d’automatisation.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Connaissance de RAID, SAN/NAS, de l’architecture x86, des systèmes d’exploitation, des infrastructures de stockage, des protocoles réseau et du diagnostic des problèmes de performance.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience avec&amp;nbsp;ServiceNow, CMDB, Jira, Confluence, Microsoft 365,&amp;nbsp;Workday&amp;nbsp;et des outils de gestion des stocks.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans la mise en œuvre d’initiatives d’automatisation ou d’amélioration continue des opérations d’infrastructure.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nos avantages&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nous proposons une offre globale de rémunération et d’avantages pouvant inclure des congés payés, des dispositifs d’épargne retraite, des bonus ou primes, des actions, la participation à notre programme d’achat d’actions pour les salariés, une couverture santé compétitive ainsi que des avantages favorisant l’équilibre familial, notamment le congé parental. Les avantages proposés par&amp;nbsp;GoDaddy&amp;nbsp;varient selon le poste et le lieu de travail et pourront être présentés plus en détail au cours du processus de recrutement.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;À propos de nous&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;GoDaddy accompagne les entrepreneurs du monde entier en leur fournissant les outils et le soutien nécessaires pour réussir en ligne et rendre les opportunités accessibles au plus grand nombre. GoDaddy permet à chacun de donner vie à son idée, de créer un site web professionnel, d’attirer des clients, de vendre ses produits et services et de gérer son activité. Notre mission est de donner à nos clients les outils, les informations et l’accompagnement nécessaires pour transformer leurs idées et leur initiative en succès. Pour en savoir plus, consultez notre page &lt;a href=&quot;https://nam10.safelinks.protection.outlook.com/?url=https%3A%2F%2Faboutus.godaddy.net%2Fabout-us%2Foverview%2Fdefault.aspx&amp;amp;data=05%7C01%7Cklilas%40godaddy.com%7C4a7c273441f14a72548908dab30d54f3%7Cd5f1622b14a345a6b069003f8dc4851f%7C0%7C0%7C638019167147789183%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=JKqNxY8z5E%2BjfKXCtVVYGLmGXuv31qCpLmWP960VLzo%3D&amp;amp;reserved=0&quot;&gt;About Us&lt;/a&gt;.&amp;nbsp;&lt;br&gt;&lt;span class=&quot;TextRun SCXW47857006 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW47857006 BCX0&quot;&gt;Chez&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW47857006 BCX0&quot;&gt;GoDaddy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW47857006 BCX0&quot;&gt;, nous sommes convaincus que la diversité des équipes contribue à créer de meilleurs produits. Notre culture valorise la diversité et l’inclusion des idées, des expériences et des perspectives. Nous intégrons les principes de diversité, d’équité, d’inclusion et d’appartenance dans notre façon de travailler, pour nos collaborateurs comme pour nos clients et nos activités. Pour en savoir plus sur nos engagements ainsi que sur nos données en matière de représentation et d’équité salariale, consultez notre rapport annuel &lt;a href=&quot;https://careers.godaddy/diversity&quot;&gt;Diversity Careers page&lt;/a&gt;.&lt;/span&gt;&lt;/span&gt; &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;sur notre page dédiée à la diversité.&lt;/span&gt; &lt;span data-contrast=&quot;none&quot;&gt;Nous célébrons également cette diversité au travers de nos C&lt;a href=&quot;https://careers.godaddy/culture&quot;&gt;ulture&lt;/a&gt;)&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW111644679 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW111644679 BCX0&quot;&gt;GoDaddy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW111644679 BCX0&quot;&gt;&amp;nbsp;est fier d’être un employeur garantissant l’égalité des chances. Les candidatures de personnes qualifiées ayant des antécédents judiciaires seront examinées conformément aux exigences légales locales et fédérales. Consultez&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight SCXW111644679 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW111644679 BCX0&quot;&gt;notre politique complète&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW111644679 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW111644679 BCX0&quot;&gt;&amp;nbsp;en matière d’égalité des chances.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW111644679 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt; &lt;em&gt;Refer to our full&lt;/em&gt; &lt;em&gt;&lt;a href=&quot;https://www.godaddy.com/legal/agreements/equal-opportunity-employment-statement&quot;&gt;EEO policy.&lt;/a&gt;&lt;/em&gt;&lt;br&gt;&lt;br&gt;&lt;span class=&quot;TextRun SCXW26905308 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;Notre équipe de recrutement est à votre disposition pour vous accompagner dans votre candidature.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW26905308 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;Si&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;vous&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;avez&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;des&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;questions&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;contactez&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight MacChromeBold SCXW26905308 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&lt;a ---------- class=&quot;TextRun Highlight SCXW26905308 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW26905308 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW226975864 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW226975864 BCX0&quot;&gt;GoDaddy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226975864 BCX0&quot;&gt;&amp;nbsp;n’accepte pas les candidatures spontanées transmises par des recruteurs ou des agences de recrutement.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW226975864 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.fr/english-speaking-jobs">English Speaking Jobs in France</a> on Arbeitnow</a>

&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Modalités de travail:&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Chez&amp;nbsp;GoDaddy, l’organisation du travail varie selon les équipes : certaines travaillent au bureau, d’autres en mode hybride, et d’autres entièrement à distance.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&amp;nbsp;&lt;br&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Sur Site:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;Ce poste s’exerce à temps plein sur site. Vous devez donc résider à une distance permettant de vous rendre régulièrement dans les locaux auxquels vous êtes rattaché(e). Vous travaillerez sur ce site dès votre premier jour&lt;/span&gt;&amp;nbsp;&lt;br&gt;&amp;nbsp;&lt;br&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Rejoignez notre équipe :&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;Chez&amp;nbsp;GoDaddy, notre infrastructure est au service de millions de clients à travers le monde. Nous recherchons un(e) Data Center Manager expérimenté(e) pour piloter les opérations, les équipes, la performance financière et la qualité des services de notre centre de données de Strasbourg.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;En tant que membre de l’équipe de management du site, vous déclinerez la stratégie de l’entreprise en actions concrètes à travers la planification des effectifs, le développement des talents, la gestion financière, la gouvernance opérationnelle et l’amélioration continue. Vous collaborerez avec les clients, les fournisseurs et les différentes équipes internes afin de garantir des opérations sûres, fiables et évolutives dans un environnement fonctionnant 24 h/24 et 7 j/7.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Votre&amp;nbsp;expérience&amp;nbsp;doit&amp;nbsp;inclure&amp;nbsp;….&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience confirmée en management et leadership, notamment dans l’encadrement de managers, le développement d’équipes responsabilisées et la conduite du changement organisationnel.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans le pilotage d’opérations au service de clients Enterprise et de services critiques pour l’activité.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience en gouvernance opérationnelle, gestion des risques, continuité d’activité, gestion budgétaire, prévisions et&amp;nbsp;reporting&amp;nbsp;auprès de la direction.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expertise technique dans au moins deux des domaines suivants : administration système (Linux et/ou Windows), réseaux, architecture des centres de données, programmation/scripting&amp;nbsp;ou automatisation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans la mise en place de programmes de formation, de développement des compétences et de planification de la relève.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&amp;nbsp;&lt;br&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Idéalement, vous disposez également de…&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Plus de 5 ans d’expérience dans les opérations de centres de données, d’infrastructures ou d’environnements critiques, avec des responsabilités croissantes en management d’équipes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Bonne connaissance des environnements Linux et Windows.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience avec Python, Bash, PowerShell, Java, Perl, Ruby, PHP ou des technologies de&amp;nbsp;scripting&amp;nbsp;similaires.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Connaissance de RAID, SAN/NAS, de l’architecture x86, des processus de démarrage, des systèmes de fichiers et d’exploitation, des réseaux, des technologies de stockage et du diagnostic d’infrastructures.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience dans la mise en œuvre d’initiatives d’automatisation, d’excellence opérationnelle ou d’amélioration des processus.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Expérience avec&amp;nbsp;ServiceNow, CMDB, Jira, Confluence, Microsoft 365,&amp;nbsp;Workday&amp;nbsp;et des outils de gestion des stocks.&lt;/span&gt; &lt;br&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nous vous encourageons à postuler même si votre expérience ou vos compétences ne correspondent pas à&amp;nbsp;tous les critères. Nous valorisons la diversité des parcours et les compétences transférables, et favorisons le développement et l’apprentissage.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nos avantages&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Nous proposons une offre globale de rémunération et d’avantages pouvant inclure des congés payés, des dispositifs d’épargne retraite, des bonus ou primes, des actions, la participation à notre programme d’achat d’actions pour les salariés, une couverture santé compétitive ainsi que des avantages favorisant l’équilibre familial, notamment le congé parental. Les avantages proposés par&amp;nbsp;GoDaddy&amp;nbsp;varient selon le poste et le lieu de travail et pourront être présentés plus en détail au cours du processus de recrutement.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;À propos de nous&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;GoDaddy accompagne les entrepreneurs du monde entier en leur fournissant les outils et le soutien nécessaires pour réussir en ligne et rendre les opportunités accessibles au plus grand nombre. GoDaddy permet à chacun de donner vie à son idée, de créer un site web professionnel, d’attirer des clients, de vendre ses produits et services et de gérer son activité. Notre mission est de donner à nos clients les outils, les informations et l’accompagnement nécessaires pour transformer leurs idées et leur initiative en succès. Pour en savoir plus, consultez notre page &lt;a href=&quot;https://nam10.safelinks.protection.outlook.com/?url=https%3A%2F%2Faboutus.godaddy.net%2Fabout-us%2Foverview%2Fdefault.aspx&amp;amp;data=05%7C01%7Cklilas%40godaddy.com%7C4a7c273441f14a72548908dab30d54f3%7Cd5f1622b14a345a6b069003f8dc4851f%7C0%7C0%7C638019167147789183%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=JKqNxY8z5E%2BjfKXCtVVYGLmGXuv31qCpLmWP960VLzo%3D&amp;amp;reserved=0&quot;&gt;About Us&lt;/a&gt;.&amp;nbsp;&lt;br&gt;&lt;span class=&quot;TextRun SCXW47857006 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW47857006 BCX0&quot;&gt;Chez&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW47857006 BCX0&quot;&gt;GoDaddy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW47857006 BCX0&quot;&gt;, nous sommes convaincus que la diversité des équipes contribue à créer de meilleurs produits. Notre culture valorise la diversité et l’inclusion des idées, des expériences et des perspectives. Nous intégrons les principes de diversité, d’équité, d’inclusion et d’appartenance dans notre façon de travailler, pour nos collaborateurs comme pour nos clients et nos activités. Pour en savoir plus sur nos engagements ainsi que sur nos données en matière de représentation et d’équité salariale, consultez notre rapport annuel &lt;a href=&quot;https://careers.godaddy/diversity&quot;&gt;Diversity Careers page&lt;/a&gt;.&lt;/span&gt;&lt;/span&gt; &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;sur notre page dédiée à la diversité.&lt;/span&gt; &lt;span data-contrast=&quot;none&quot;&gt;Nous célébrons également cette diversité au travers de nos C&lt;a href=&quot;https://careers.godaddy/culture&quot;&gt;ulture&lt;/a&gt;)&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW111644679 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW111644679 BCX0&quot;&gt;GoDaddy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW111644679 BCX0&quot;&gt;&amp;nbsp;est fier d’être un employeur garantissant l’égalité des chances. Les candidatures de personnes qualifiées ayant des antécédents judiciaires seront examinées conformément aux exigences légales locales et fédérales. Consultez&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight SCXW111644679 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW111644679 BCX0&quot;&gt;notre politique complète&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW111644679 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW111644679 BCX0&quot;&gt;&amp;nbsp;en matière d’égalité des chances.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW111644679 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt; &lt;em&gt;Refer to our full&lt;/em&gt; &lt;em&gt;&lt;a href=&quot;https://www.godaddy.com/legal/agreements/equal-opportunity-employment-statement&quot;&gt;EEO policy.&lt;/a&gt;&lt;/em&gt;&lt;br&gt;&lt;br&gt;&lt;span class=&quot;TextRun SCXW26905308 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;Notre équipe de recrutement est à votre disposition pour vous accompagner dans votre candidature.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW26905308 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;Si&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;vous&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;avez&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;des&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;questions&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW26905308 BCX0&quot;&gt;contactez&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight MacChromeBold SCXW26905308 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;&lt;a ---------- class=&quot;TextRun Highlight SCXW26905308 BCX0&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW26905308 BCX0&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW26905308 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW226975864 BCX0&quot; lang=&quot;FR-FR&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW226975864 BCX0&quot;&gt;GoDaddy&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW226975864 BCX0&quot;&gt;&amp;nbsp;n’accepte pas les candidatures spontanées transmises par des recruteurs ou des agences de recrutement.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW226975864 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[220,720],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,1]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.fr/english-speaking-jobs">English Speaking Jobs in France</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;h4&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;WPP Enterprise Solutions designs, builds, and operates the growth systems that competitive businesses rely on. In a world where Al is reshaping how companies drive growth, we lead clients in business transformation and marketing modernization, connecting strategy directly to execution. Our 12,000 experts in engineering and platforms, commerce, consulting, content transformation, CRM, and CX work within a unified global operating unit across 40+ markets. WPP Enterprise Solutions works alongside best-in-class partners including Adobe, AWS, Braze, Google, Microsoft, Salesforce, and Shopify, as well as innovators in AI, to deliver growth solutions tailored to the needs of our clients’ businesses. VML, part of WPP, supports WPP Enterprise Solutions by helping brands activate transformation through creativity and experience.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Nous recrutons, pour renforcer nos équipes Sales, un.e Head of Alliances.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Missions&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;En tant que Head of Alliances, vous pilotez le go-to-market de WPP Enterprise Solutions avec nos partenaires technologiques stratégiques (Adobe, AWS, Braze, Google, Microsoft, Salesforce, Shopify) et les innovateurs de l’IA. Point de convergence entre nos partenaires, nos équipes commerciales et nos Business Units, vous transformez la force de l’écosystème en pipeline, en différenciation et en croissance. Comme l’ensemble de l’équipe de Business Développement, vous reposez sur un profil hybride dont les 2 piliers sont d’être :&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Responsable du go-to-market conjoint avec nos partenaires technologiques stratégiques : co-construction des offres, des plans d’affaires et de la démarche de co-selling autour de nos &lt;em&gt;capabilities &lt;/em&gt;auprès de clients et prospects,&lt;/li&gt;
&lt;li&gt;Orchestrateur de l’écosystème en interne : enablement des équipes, montée en compétence et certifications sur les plateformes partenaires, pour activer la bonne expertise au sein de WPP Enterprise Solutions et du réseau WPP&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Cette hybridation est la clé du succès : être à la fois moteur du business généré via l’écosystème partenaires et garant de la capacité des équipes à délivrer avec ces technologies.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Dimension Business :&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Définit et déploie la stratégie de go-to-market et de marketing partenaires de WPP Enterprise Solutions avec ses partenaires technologiques stratégiques, afin de maximiser la valeur, la différenciation et le pipeline générés par l’écosystème,&lt;/li&gt;
&lt;li&gt;Construit et anime les plans d’affaires conjoints (joint business plans) avec chaque partenaire clé (Adobe, AWS, Braze, Google, Microsoft, Salesforce, Shopify…), en pilotant objectifs, jalons et indicateurs de performance partagés,&lt;/li&gt;
&lt;li&gt;Orchestre le co-selling et le co-marketing : aligne partenaires, équipes commerciales et Business Units pour transformer les opportunités de l’écosystème en deals, du sourcing à la conversion,&lt;/li&gt;
&lt;li&gt;Conçoit et orchestre le plan d’événements dédiés ou co-construits avec les partenaires (webinaires, ateliers, salons, temps forts commerciaux), afin de générer visibilité, demande et pipeline,&lt;/li&gt;
&lt;li&gt;Met en œuvre, en continu, l’excellence de la démarche partenaires via les processus et outils internes ainsi que les portails partenaires, à des fins de visibilité, de pilotage et d’animation globale en interne,&lt;/li&gt;
&lt;li&gt;Sécurise et défend les intérêts économique et contractuel de WPP Enterprise Solutions dans le cadre des accords de partenariat (referral, reselling, MDF, niveaux de partenariat),&lt;/li&gt;
&lt;li&gt;Pilote le niveau de préférence et de mindshare de nos partenaires à notre égard : positionne WPP Enterprise Solutions comme partenaire de référence dans leur écosystème, fait progresser notre niveau de partenariat et suit la performance des objectifs conjoints,&lt;/li&gt;
&lt;li&gt;Contribue au thought leadership de WPP Enterprise Solutions sur les enjeux d’écosystème et de plateformes (IA, data, commerce, CX), via des prises de parole conjointes valorisant nos réussites dans une logique de ROI business,&lt;/li&gt;
&lt;li&gt;Construit et fait vivre un patrimoine de connaissances sur l’écosystème technologique (roadmaps produits, niveaux et programmes de partenariat, dispositifs de financement) afin d’accélérer et de fluidifier l’action commerciale,&lt;/li&gt;
&lt;li&gt;Incarne, diffuse et fait vivre l’excellence du modèle partenaires en interne, en particulier auprès des communautés commerciale et managériale, pour l’inspirer et développer son réflexe écosystème.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;Dimension Enablement &amp;amp; Delivery :&lt;/em&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Travaille de concert avec le CTO, à qui revient la responsabilité de l’enablement, des certifications et de la montée en compétences des équipes sur les plateformes partenaires ; il s’assure que ces chantiers progressent au rythme des priorités business et des engagements pris auprès des partenaires,&lt;/li&gt;
&lt;li&gt;Veille à la disponibilité et à la capitalisation des assets conjoints (cas clients, références, supports de co-vente) et au partage des retours d’expérience.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Profil recherché&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Vous justifiez de 5 à 10 ans d’expérience, dont une expérience significative en alliances / partenariats technologiques, channel ou business development – idéalement acquise en cabinet de conseil, ESN, agence ou chez un éditeur / hyperscaler.&lt;/p&gt;
&lt;p&gt;Notre croissance reposant sur un écosystème de partenaires technologiques (Adobe, AWS, Braze, Google, Microsoft, Salesforce, Shopify…), vous maîtrisez les mécaniques de co-selling, de co-marketing et de joint business planning.&lt;/p&gt;
&lt;p&gt;Vous pouvez justifier de contributions ou de succès significatifs dans le cadre d’initiatives partenaires ou de développement business, au-delà d’en comprendre la logique ou les bonnes pratiques.&lt;/p&gt;
&lt;p&gt;Votre capacité à nouer des relations de grande qualité, tant avec les équipes partenaires (alliance managers, channel, avant-vente) qu’avec les décideurs internes (Directions commerciales, Business Units, Marketing), fait de vous un orchestrateur d’écosystème performant, du sourcing d’opportunités à la conclusion de deals conjoints équilibrant les intérêts du partenaire, du client et de WPP Enterprise Solutions.&lt;/p&gt;
&lt;p&gt;Les enjeux des plateformes technologiques et de l’écosystème IA / data / commerce vous passionnent, et vous savez vous appuyer sur vos expériences pour bâtir un discours solide en interne comme auprès des partenaires.&lt;/p&gt;
&lt;p&gt;Votre rigueur et votre curiosité font de vous un acteur à la fois à l’aise dans la logique de développement business sur des clients existants que sur de la conquête opportuniste, ou en relai d’un partenaire.&lt;/p&gt;
&lt;p&gt;La maîtrise de l’anglais, à l’oral comme à l’écrit, est indispensable : vous adressez des partenaires et des interlocuteurs internationaux de manière totalement autonome.&lt;/p&gt;
&lt;p&gt;Tous nos postes sont ouverts aux personnes en situation de handicap.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Ce que nous proposons&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Remote partiel&lt;/li&gt;
&lt;li&gt;Prise en charge à 75% des transports en commun&lt;/li&gt;
&lt;li&gt;Une carte restaurant à 11€/jour&lt;/li&gt;
&lt;li&gt;Cours d&#39;anglais, massages, yoga&lt;/li&gt;
&lt;li&gt;Soirées et team building réguliers&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Pourquoi nous rejoindre ?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Intégrer WPP Enterprise Solutions, c’est choisir d’évoluer dans un environnement dynamique, humain et innovant, propice au développement de chacun, à la réalisation de missions enrichissantes et aux évolutions de carrière. Nous rejoindre, c’est participer à une aventure collective au service de l’épanouissement personnel.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h4&gt;&lt;strong&gt;About WPP&lt;/strong&gt;&lt;/h4&gt;
&lt;p class=&quot;p1&quot;&gt;WPP is the trusted growth partner for the world’s leading brands. With exceptional talent, trusted data and intelligence and world-class partnerships – all united by our agentic marketing platform, WPP Open – we help clients navigate change, capture opportunity and deliver transformational growth. For more information, visit &lt;a href=&quot;http://wpp.com/&quot;&gt;&lt;span class=&quot;s1&quot;&gt;WPP.com&lt;/span&gt;&lt;/a&gt;&lt;span class=&quot;s2&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;normaltextrun&quot;&gt;&lt;span lang=&quot;EN-GB&quot;&gt;WPP (VML/WPP Enterprise Solutions) is an equal opportunity employer and considers applicants for all positions without discrimination or regard to characteristics. We are committed to fostering a culture of respect in which everyone feels they belong and has the same opportunities to progress in their careers.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;scxw176048299&quot;&gt;&lt;span lang=&quot;EN-GB&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;When you click &quot;Submit Application&quot;, this will send any information you add below to WPP (VML/WPP Enterprise Solutions). Before you do this, we think it&#39;s a good idea to read through our &lt;a href=&quot;https://www.vml.com/recruitment-privacy-policy&quot;&gt;Recruitment Privacy Policy&lt;/a&gt;. California residents should read our&amp;nbsp;&lt;a href=&quot;https://www.vml.com/california-recruitment-privacy-notice&quot;&gt;California Recruitment Privacy Notice&lt;/a&gt;. This explains what we do with your personal data when you apply for a role with us, and, how you can update the information you have provided us with or how to remove it.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.fr">Jobs in France</a> on Arbeitnow</a>

&lt;p&gt;At Databricks we work on some of the most complex distributed processing and machine learning problems in the world and our customers challenge us with interesting new big data and AI use cases. You will shape the future of big data and the machine learning landscape for leading Fortune 500 organizations.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Forward Deployed Engineering (FDE) Delivery Partner Manager &lt;/strong&gt;supports the mission of the Professional Services team, which is to&lt;strong&gt; accelerate and de-risk our customers&#39; business outcomes&lt;/strong&gt; through effective enablement and delivery of Databricks platform technology. This is an individual contributor role that will oversee the Databricks Delivery Partner Program which looks to use close partnerships with key system integrators to effectively co-deliver Databricks services engagements.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The impact you will have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You will work with the FDE team in order to use &lt;strong&gt;Databricks delivery partners to accelerate our customer project outcomes&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Build and develop FDE relationships with &lt;strong&gt;Global System Integrators (GSIs), Regional System Integrators (RSIs), regional Partner team &lt;/strong&gt;to support bi-directional pipeline review and bi-directional engagements (subcontracting, and advisory) for company priorities.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Build a &lt;strong&gt;RFP process&lt;/strong&gt; to support Partner Selection for large complex multi year, multi phase &lt;strong&gt;migration&lt;/strong&gt; deals. Create templates, scorecards to supplement partner selection with a data driven approach.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Spearhead and lead efforts to incubate and ramp new partners with &lt;strong&gt;Gen AI&lt;/strong&gt; capabilities.&lt;/li&gt;
&lt;li&gt;Drive MBRs and QBRs with &lt;strong&gt;priority partners&lt;/strong&gt;, and develop long term roadmaps for PS Partner delivery priorities. Develop scorecards and feedback loops to segment partners by focus areas, regions and company priorities.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Drive&lt;strong&gt; delivery governance&lt;/strong&gt; to ensure partner quality and delivery on Services led and partner supported implementations. Support global programs to measure partner quality such as CSAT, Partner Survey and program governance.&lt;/li&gt;
&lt;li&gt;Lead programs that align with our &lt;strong&gt;FDE &amp;amp; Partner strategy &lt;/strong&gt;for Assurance and advisory services. Work with our cross-functional channel teams to enable GSIs, RSIs, SIs on Assurance services, and support bi-weekly reviews and deal governance&lt;/li&gt;
&lt;li&gt;Support &lt;strong&gt;Partner IP efforts&lt;/strong&gt; such as the creation of service delivery kits to better scale our ecosystem.&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Liaison with Delivery Partner organizations to ensure personnel have the required level of training and certification in order to achieve Databricks projects following best practices. Champion and provide thought leadership for &lt;strong&gt;specialization &lt;/strong&gt;programs. You will implement and lead programs for achieving requirements and exceeding delivery quality.&lt;/li&gt;
&lt;li&gt;Build and maintain an &lt;strong&gt;effective onboarding process for partner resources&lt;/strong&gt; ensuring effective utilization and quality of services across Databricks customer deliveries.&lt;/li&gt;
&lt;li&gt;Work with the &lt;strong&gt;Databricks resource management team &lt;/strong&gt;to oversee the pipeline planning process with each of the delivery partners, ensuring partner resource availability in a timely manner to support Databricks services opportunities.&lt;/li&gt;
&lt;li&gt;Allocation and outsourcing of Projects to Services partners. This includes selecting the appropriate partner for the project and working with the partner closely to ensure project success.&lt;/li&gt;
&lt;li&gt;Work with our legal, people operations and other cross functional organization to &lt;strong&gt;support bi directional contractual negotiations&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Advocate for the Partner&#39;s needs internally; managing any escalations and issues on projects being delivered by partners.&lt;/li&gt;
&lt;li&gt;Develop, implement, and monitor Key Performance Indicators for each Services partner.&lt;/li&gt;
&lt;li&gt;Coach, Mentor junior members of the team, and partner resource&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What we look for:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Extensive industry experience including resource management and demand pipeline management and record of success in navigating and driving engagements with large enterprise organizations with a focus on FDE&lt;/li&gt;
&lt;li&gt;Extensive experience within a FDE or consulting organization as a partner Manager, and/or Consulting Manager.&lt;/li&gt;
&lt;li&gt;Experience managing partner or third-party organization enablement including upskilling teams to provide delivery capabilities.&lt;/li&gt;
&lt;li&gt;Excel at working directly with Partners and customers to gather, prioritize, plan and execute solutions to customer business requirements as they relate to technology.&lt;/li&gt;
&lt;li&gt;Experience managing commercial agreements with partners including statements of works to support services management.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Databricks&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;Databricks is the Data and AI company. More than 20,000 organizations worldwide — including adidas, AT&amp;amp;T, Bayer, Block, Mastercard, Rivian, Unilever, and 70% of the Fortune 500 — rely on the Databricks Data + AI Platform to build and scale data and AI apps, analytics and agents. Headquartered in San Francisco with 30+ offices around the globe, Databricks offers a unified platform that includes Genie, Lakebase, Agent Bricks, Lakeflow, Lakehouse, and Unity Catalog. To learn more, follow Databricks on &lt;a href=&quot;https://www.linkedin.com/company/databricks&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://x.com/databricks&quot;&gt;X&lt;/a&gt;, &lt;a href=&quot;https://www.youtube.com/@Databricks&quot;&gt;YouTube&lt;/a&gt;, and &lt;a href=&quot;https://www.instagram.com/databricksinc/?hl=en&quot;&gt;Instagram&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Benefits&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;At Databricks, we strive to provide comprehensive benefits and perks that meet the needs of all of our employees. For specific details on the benefits offered in your region click &lt;a href=&quot;https://docs.google.com/document/d/154un3e8Xav4BceOSlcYFZRGEuQI54xMxVydRwQn54eQ/edit?usp=sharing&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Diversity and Inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Databricks, we are committed to fostering a diverse and inclusive culture where everyone can excel. We take great care to ensure that our hiring practices are inclusive and meet equal employment opportunity standards. Individuals looking for employment at Databricks are considered without regard to age, color, disability, ethnicity, family or marital status, gender identity or expression, language, national origin, physical and mental ability, political affiliation, race, religion, sexual orientation, socio-economic status, veteran status, and other protected characteristics.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Compliance&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If access to export-controlled technology or source code is required for performance of job duties, it is within Employer&#39;s discretion whether to apply for a U.S. government license for such positions, and Employer may decline to proceed with an applicant on this basis alone.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.fr/english-speaking-jobs">English Speaking Jobs in France</a> on Arbeitnow</a>

&lt;p&gt;FEQ227R207&lt;/p&gt;
&lt;p&gt;As a Field Engineering Manager, you will lead a talented team of technical pre-sales Solutions Architects and Solutions Engineers based in France. You’ll play a key leadership role at the intersection of technology and business, helping our teams design value-based solutions and drive growth through effective collaboration with Sales.&lt;/p&gt;
&lt;p&gt;You’ll coach your team to communicate complex ideas clearly, support strategic sales cycles, and build strong partnerships with customers and stakeholders across large organisations.&lt;/p&gt;
&lt;p&gt;The impact you will have:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead, mentor, and develop a high-performing pre-sales team in France.&lt;/li&gt;
&lt;li&gt;Foster an inclusive and collaborative culture that reflects Databricks’ values of customer obsession, teamwork, and diversity.&lt;/li&gt;
&lt;li&gt;Partner with Sales to drive growth through solution- and value-based selling.&lt;/li&gt;
&lt;li&gt;Enhance team effectiveness by establishing best practices that improve efficiency and focus on business impact.&lt;/li&gt;
&lt;li&gt;Build trusted relationships with customer executives and strategic partners.&lt;/li&gt;
&lt;li&gt;Collaborate across teams—including Marketing, Sales, and Services—to ensure seamless implementation and customer success.&lt;/li&gt;
&lt;li&gt;Represent Databricks as part of the regional leadership team and contribute to building our brand and presence in the market.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;What we look for:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proven experience managing technical teams in Big Data, Cloud, or SaaS environments.&lt;/li&gt;
&lt;li&gt;A track record of leading, mentoring, and scaling pre-sales or technical field organisations.&lt;/li&gt;
&lt;li&gt;Understanding of consumption-based business models.&lt;/li&gt;
&lt;li&gt;Ability to collaborate effectively with Sales and other cross-functional leaders.&lt;/li&gt;
&lt;li&gt;Strong communication and interpersonal skills—fluent in English and native-level French.&lt;/li&gt;
&lt;li&gt;Technical background in Data Engineering, Databases, or Data Science (consulting experience is a plus).&lt;/li&gt;
&lt;li&gt;Passion for data, AI, and cloud technologies and the ability to articulate their business value clearly.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Note: Location for the role is in Paris (i.e. within commutable distance).&lt;/p&gt;
&lt;p&gt;#LI-hybrid&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Databricks&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;Databricks is the Data and AI company. More than 20,000 organizations worldwide — including adidas, AT&amp;amp;T, Bayer, Block, Mastercard, Rivian, Unilever, and 70% of the Fortune 500 — rely on the Databricks Data + AI Platform to build and scale data and AI apps, analytics and agents. Headquartered in San Francisco with 30+ offices around the globe, Databricks offers a unified platform that includes Genie, Lakebase, Agent Bricks, Lakeflow, Lakehouse, and Unity Catalog. To learn more, follow Databricks on &lt;a href=&quot;https://www.linkedin.com/company/databricks&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://x.com/databricks&quot;&gt;X&lt;/a&gt;, &lt;a href=&quot;https://www.youtube.com/@Databricks&quot;&gt;YouTube&lt;/a&gt;, and &lt;a href=&quot;https://www.instagram.com/databricksinc/?hl=en&quot;&gt;Instagram&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Benefits&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;At Databricks, we strive to provide comprehensive benefits and perks that meet the needs of all of our employees. For specific details on the benefits offered in your region click &lt;a href=&quot;https://docs.google.com/document/d/154un3e8Xav4BceOSlcYFZRGEuQI54xMxVydRwQn54eQ/edit?usp=sharing&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Diversity and Inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Databricks, we are committed to fostering a diverse and inclusive culture where everyone can excel. We take great care to ensure that our hiring practices are inclusive and meet equal employment opportunity standards. Individuals looking for employment at Databricks are considered without regard to age, color, disability, ethnicity, family or marital status, gender identity or expression, language, national origin, physical and mental ability, political affiliation, race, religion, sexual orientation, socio-economic status, veteran status, and other protected characteristics.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Compliance&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If access to export-controlled technology or source code is required for performance of job duties, it is within Employer&#39;s discretion whether to apply for a U.S. government license for such positions, and Employer may decline to proceed with an applicant on this basis alone.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.fr/english-speaking-jobs">English Speaking Jobs in France</a> on Arbeitnow</a>

&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;SLSQ427R1101&lt;/p&gt;
&lt;p&gt;As an Emerging Enterprise Account Executive at Databricks, you come with relevant experience selling to Emerging Enterprise ($250 - $1B revenue) accounts in France. As a successful candidate you are a self-starter who understands the consumption sales process. You know how to sell innovation and value to existing customers, identify new use cases and grow consumption and can guide deals forward to compress decision cycles. You love understanding a product in-depth and are passionate about communicating its value to customers and partners. You will be offered huge potential for career progression with the pace of the team&#39;s growth.&lt;/p&gt;
&lt;p&gt;&lt;br&gt;&lt;strong&gt;The impact you will have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Assess your territory and develop a successful execution strategy&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Drive quarter-on-quarter consumption growth in existing accounts&lt;/li&gt;
&lt;li&gt;Exceed activity and quarterly revenue targets&lt;/li&gt;
&lt;li&gt;Track all customer details including use case, purchase time frames, next steps, and forecasting in Salesforce&lt;/li&gt;
&lt;li&gt;Identify new use case opportunities and showcase value to existing customers&lt;/li&gt;
&lt;li&gt;Promote the value of the Databricks&#39; Data Intelligence Platform&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Ensure 100% satisfaction among all customers&lt;/li&gt;
&lt;li&gt;Connect to your accounts ecosystem (stakeholders, influencers, partners, VC, PE, cloud providers etc)&lt;/li&gt;
&lt;li&gt;Drive both technical and business discussions, adapting the narrative to the audience (C level, middle management, practitioner…) and persona (IT, Data &amp;amp; AI, Finance, Operations, Marketing, Sales…)&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What we look for:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong closing experience selling SaaS / Cloud or Big Data/AI solutions to Mid Market Customers in France (Digital Native experience is highly desirable)&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Solution and business-outcomes focused sales approach (Command of the Message, MEDDPIC, Challenger Sale)&lt;/li&gt;
&lt;li&gt;Ability to simply articulate intricate cloud &amp;amp; big data / AI technologies and their business value for the customer&lt;/li&gt;
&lt;li&gt;Experience exceeding sales targets/quotas&lt;/li&gt;
&lt;li&gt;Master’s Degree or relevant work experience&lt;/li&gt;
&lt;li&gt;Fluency in English and French is required&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Databricks&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;Databricks is the Data and AI company. More than 20,000 organizations worldwide — including adidas, AT&amp;amp;T, Bayer, Block, Mastercard, Rivian, Unilever, and 70% of the Fortune 500 — rely on the Databricks Data + AI Platform to build and scale data and AI apps, analytics and agents. Headquartered in San Francisco with 30+ offices around the globe, Databricks offers a unified platform that includes Genie, Lakebase, Agent Bricks, Lakeflow, Lakehouse, and Unity Catalog. To learn more, follow Databricks on &lt;a href=&quot;https://www.linkedin.com/company/databricks&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://x.com/databricks&quot;&gt;X&lt;/a&gt;, &lt;a href=&quot;https://www.youtube.com/@Databricks&quot;&gt;YouTube&lt;/a&gt;, and &lt;a href=&quot;https://www.instagram.com/databricksinc/?hl=en&quot;&gt;Instagram&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Benefits&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;At Databricks, we strive to provide comprehensive benefits and perks that meet the needs of all of our employees. For specific details on the benefits offered in your region click &lt;a href=&quot;https://docs.google.com/document/d/154un3e8Xav4BceOSlcYFZRGEuQI54xMxVydRwQn54eQ/edit?usp=sharing&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Diversity and Inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Databricks, we are committed to fostering a diverse and inclusive culture where everyone can excel. We take great care to ensure that our hiring practices are inclusive and meet equal employment opportunity standards. Individuals looking for employment at Databricks are considered without regard to age, color, disability, ethnicity, family or marital status, gender identity or expression, language, national origin, physical and mental ability, political affiliation, race, religion, sexual orientation, socio-economic status, veteran status, and other protected characteristics.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Compliance&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If access to export-controlled technology or source code is required for performance of job duties, it is within Employer&#39;s discretion whether to apply for a U.S. government license for such positions, and Employer may decline to proceed with an applicant on this basis alone.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.fr">Jobs in France</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;Zscaler (NASDAQ: ZS) accelerates digital transformation so customers can be more agile, efficient, resilient, and secure. The Zscaler Zero Trust Exchange platform protects thousands of customers from cyberattacks and data loss by securely connecting users, devices, and applications in any location. Distributed across 200+ public data centers globally and thousands of private sites at the edge, the SASE-based Zero Trust Exchange is the world’s largest in-line cloud security platform.&lt;/p&gt;
&lt;p&gt;We believe the future of work is Human + AI and are building an AI-native enterprise where human potential is amplified by machine intelligence to solve the world’s hardest security challenges. Driven by deep customer obsession, we are committed to the mission, outcome, and to each other. We bring these commitments to life through three core behaviors: ownership and collaboration, trust through outcomes and impact, and a challenge culture with ongoing feedback. Ready to make an impact at the company pioneering security transformation in the AI era? Join us at Zscaler.&lt;/p&gt;&lt;/div&gt;&lt;p data-path-to-node=&quot;0&quot;&gt;&lt;strong data-path-to-node=&quot;0&quot; data-index-in-node=&quot;0&quot;&gt;Role&lt;/strong&gt;&lt;/p&gt;
&lt;p data-path-to-node=&quot;0&quot;&gt;We are looking for a Sales Engineer to join our team. This is a France, Paris (Remote) role, reporting to the Sales Engineering Manager in the Sales Engineering department. You will act as a pivotal technical partner, presenting the Zscaler cloud security platform to prospective customers and translating complex goals into enticing, relevant recommendations. Your mission is to serve as a trusted advisor, guiding clients through their transformational journeys with deep technical expertise and strategic vision.&lt;/p&gt;
&lt;p data-path-to-node=&quot;1&quot;&gt;&lt;strong data-path-to-node=&quot;1&quot; data-index-in-node=&quot;0&quot;&gt;What you’ll do (Role Expectations)&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;2&quot;&gt;
&lt;li&gt;Present the Zscaler cloud security platform to prospective customers&lt;/li&gt;
&lt;li&gt;Set the vision and translate goals into enticing and relevant recommendations&lt;/li&gt;
&lt;li&gt;Act as a trusted advisor to clients while aiding their transformational journey&lt;/li&gt;
&lt;li&gt;Gather customer technical requirements and promote the value proposition in POV, presentations, and demos&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;3&quot;&gt;&lt;strong data-path-to-node=&quot;3&quot; data-index-in-node=&quot;0&quot;&gt;Who You Are (Success Profile)&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;4&quot;&gt;
&lt;li&gt;You thrive in ambiguity. You&#39;re comfortable building the path as you walk it. You thrive in a dynamic environment, seeing ambiguity not as a hindrance, but as the raw material to build something meaningful.&lt;/li&gt;
&lt;li&gt;You act like an owner. Your passion for the mission fuels your bias for action. You operate with integrity because you genuinely care about the outcome. True ownership involves leveraging dynamic range: the ability to navigate seamlessly between high-level strategy and hands-on execution.&lt;/li&gt;
&lt;li&gt;You are a problem-solver. You love running towards the challenges because you are laser-focused on finding the solution, knowing that solving the hard problems delivers the biggest impact.&lt;/li&gt;
&lt;li&gt;You are a high-trust collaborator. You are ambitious for the team, not just yourself. You embrace our challenge culture by giving and receiving ongoing feedback—knowing that candor delivered with clarity and respect is the truest form of teamwork and the fastest way to earn trust.&lt;/li&gt;
&lt;li&gt;You are a learner. You have a true growth mindset and are obsessed with your own development, actively seeking feedback to become a better partner and a stronger teammate. You love what you do and you do it with purpose.&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;5&quot;&gt;&lt;strong data-path-to-node=&quot;5&quot; data-index-in-node=&quot;0&quot;&gt;What We’re Looking for (Minimum Qualifications)&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Foundational understanding of AI/ML technologies and experience leveraging, securing, or positioning AI-driven solutions to optimize outcomes within your functional domain&lt;/li&gt;
&lt;li&gt;5+ years of experience as a Sales Engineer or Solutions Consultant&lt;/li&gt;
&lt;li&gt;Knowledge of enterprise network or cloud security technologies&lt;/li&gt;
&lt;li&gt;Experience working with Value Selling Methodologies as well as collaborating with sales to identify, qualify, and scope opportunities while delivering presentations, demos, and proof of concept engagements&lt;/li&gt;
&lt;li&gt;Fluency in French&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;7&quot;&gt;&lt;strong data-path-to-node=&quot;7&quot; data-index-in-node=&quot;0&quot;&gt;What Will Make You Stand Out (Preferred Qualifications)&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;8&quot;&gt;
&lt;li&gt;Experience positioning AI-driven threat intelligence, automated policy enforcement, or AI security frameworks to enterprise clients&lt;/li&gt;
&lt;li&gt;Cloud Platform and other relevant certifications such as CISSP or CCNP&lt;/li&gt;
&lt;li&gt;Technical experience in SASE, Proxy technology, Cybersecurity, IPS, DLP, CASB, or CNAPP&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;9&quot;&gt;#LI-Remote&lt;/p&gt;
&lt;p data-path-to-node=&quot;9&quot;&gt;#LI-LS2&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p data-pm-slice=&quot;1 3 []&quot;&gt;At Zscaler, we are committed to building a team that reflects the communities we serve and the customers we work with. We foster an inclusive environment that values all backgrounds and perspectives, emphasizing collaboration and belonging. Join us in our mission to make doing business seamless and secure.&lt;/p&gt;
&lt;p&gt;Our Benefits program is one of the most important ways we support our employees. Zscaler proudly offers comprehensive and inclusive benefits to meet the diverse needs of our employees and their families throughout their life stages, including:&lt;/p&gt;
&lt;div class=&quot;has-nudge&quot; data-nudge-id=&quot;5eb9419b-6a4d-4451-bfa6-e2eb96084be0&quot;&gt;
&lt;ul&gt;
&lt;li&gt;Various health plans&lt;/li&gt;
&lt;li&gt;Time off plans for vacation and sick time&lt;/li&gt;
&lt;li&gt;Parental leave options&lt;/li&gt;
&lt;li&gt;Retirement options&lt;/li&gt;
&lt;li&gt;Education reimbursement&lt;/li&gt;
&lt;li&gt;In-office perks, and more!&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;has-nudge&quot; data-nudge-id=&quot;5eb9419b-6a4d-4451-bfa6-e2eb96084be0&quot;&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;Learn more about Zscaler&#39;s hybrid working model and benefits&amp;nbsp;&lt;a href=&quot;https://www.zscaler.com/candidate-resource-hub&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;By applying for this role, you adhere to applicable laws, regulations, and Zscaler policies, including those related to security and privacy standards and guidelines.&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;Zscaler is committed to providing equal employment opportunities to all individuals. We strive to create a workplace where employees are treated with respect and have the chance to succeed. All qualified applicants will be considered for employment without regard to race, color, religion, sex (including pregnancy or related medical conditions), age, national origin, sexual orientation, gender identity or expression, genetic information, disability status, protected veteran status, or any other characteristic protected by federal, state, or local laws. &lt;em&gt;See more information by clicking on the &lt;/em&gt;&lt;a href=&quot;https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12ScreenRdr.pdf&quot;&gt;&lt;em&gt;Know Your Rights: Workplace Discrimination is Illegal &lt;/em&gt;&lt;/a&gt;&lt;em&gt;link.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;Pay Transparency&lt;/p&gt;
&lt;p&gt;Zscaler complies with all applicable federal, state, and local pay transparency rules.&lt;/p&gt;
&lt;p&gt;Zscaler is committed to providing reasonable support (called accommodations or adjustments) in our recruiting processes for candidates who are differently abled, have long term conditions, mental health conditions or sincerely held religious beliefs, or who are neurodivergent or require pregnancy-related support.&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.fr/english-speaking-jobs">English Speaking Jobs in France</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;&lt;strong&gt;About Anthropic&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Anthropic’s mission is to create reliable, interpretable, and steerable AI systems. We want AI to be safe and beneficial for our users and for society as a whole. Our team is a quickly growing group of committed researchers, engineers, policy experts, and business leaders working together to build beneficial AI systems.&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;À propos du poste&lt;/h2&gt;
&lt;p&gt;Ce poste de direction est essentiel : il consiste à construire et à faire passer à l’échelle les partenariats d’Anthropic avec les cabinets de conseil, les intégrateurs de systèmes mondiaux (GSI) et les boutiques partenaires nativement IA en France.&lt;/p&gt;
&lt;p&gt;Vous travaillerez en étroite collaboration avec l’équipe commerciale pour que les clients adoptent l’IA grâce à nos partenaires.&lt;/p&gt;
&lt;p&gt;Ce poste est un poste de construction, et non de gestion. Compte tenu du stade de développement d’Anthropic, nous recherchons un profil qui a déjà fait ses preuves en faisant passer des partenariats de zéro à des moteurs de revenus à grande échelle, un profil qui a bâti ces relations de A à Z, et non simplement hérité de relations existantes pour les gérer.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Responsabilités&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Partenariats et exécution&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Vous collaborerez étroitement avec l’équipe commerciale pour comprendre comment les partenaires peuvent soutenir l’adoption de Claude par les clients.&lt;/li&gt;
&lt;li&gt;Vous accompagnerez les partenaires dans la création de solutions clients reproductibles, répondant à des cas d’usage précis dans de nombreux secteurs : services financiers, santé, distribution, industrie, secteur public et services professionnels.&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;Performance et pilotage des indicateurs clés (KPI)&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Vous portez la responsabilité des indicateurs clés de performance et vous les pilotez : revenus influencés par les partenaires, livraison réalisée par les partenaires, nombre de personnes consultantes formées et certifiées.&lt;/li&gt;
&lt;li&gt;Chaque deal influencé par votre portefeuille de partenaires doit être conçu pour la réussite du client et la croissance de sa valeur à long terme. Vous définirez des critères de réussite pour les comptes communs, veillerez à la qualité de la mise en œuvre et de l’accompagnement à l’adoption, et mettrez en place des boucles de retour d’expérience favorisant l’amélioration continue.&lt;/li&gt;
&lt;li&gt;Vous rendrez compte de la santé des partenariats, de leur avancement et de leurs résultats commerciaux, en vous appuyant sur des analyses fondées sur les données.&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;Développement du marché et construction de la marque&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Vous renforcerez la notoriété de la marque Anthropic en France grâce à des relations stratégiques avec les partenaires.&lt;/li&gt;
&lt;li&gt;Vous élaborerez et déploierez des stratégies de mise sur le marché (GTM) propres à chaque marché, adaptées aux pratiques commerciales et aux nuances culturelles locales.&lt;/li&gt;
&lt;li&gt;Vous composerez avec les enjeux locaux de réglementation, de conformité et de souveraineté des données.&lt;/li&gt;
&lt;li&gt;Vous créerez un avantage concurrentiel grâce aux capacités singulières des partenaires et à des propositions de valeur élaborées en commun.&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Votre profil&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Ce poste pourrait vous convenir si vous réunissez les atouts suivants :&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Vous avez l’esprit d’initiative et le goût de construire : vous êtes à l’aise pour partir de zéro et créer des partenariats d’envergure.&lt;/li&gt;
&lt;li&gt;Vous maîtrisez l’anglais et le français.&lt;/li&gt;
&lt;li&gt;Vous comptez au moins 8 ans d’expérience dans les partenariats technologiques à destination des entreprises, idéalement dans le cloud, l’IA/ML ou les activités de plateforme.&lt;/li&gt;
&lt;li&gt;Vous avez une culture de la donnée, tournée vers les résultats mesurables et l’atteinte des KPI, et un historique avéré de revenus additionnels générés grâce aux partenariats dans la région.&lt;/li&gt;
&lt;li&gt;Vous avez démontré votre capacité à assurer la réussite des clients et la protection de la marque via les canaux partenaires.&lt;/li&gt;
&lt;li&gt;Vous avez l’esprit de compétition : la victoire et la différenciation sont votre moteur.&lt;/li&gt;
&lt;li&gt;Vous avez une approche collaborative et savez travailler de façon transversale avec les équipes commerciales, produit, marketing et régionales.&lt;/li&gt;
&lt;li&gt;Vous nourrissez une vraie passion pour l’IA et vous vous reconnaissez dans la mission d’Anthropic : développer une IA bénéfique.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Relations de travail&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Votre rattachement hiérarchique se fera auprès de la direction des partenariats internationaux, tandis que votre activité quotidienne sera pilotée par la personne responsable des partenariats EMEA Sud. Vous travaillerez également en étroite collaboration avec la direction commerciale régionale d’Anthropic et ses Account Executives, ainsi qu’avec les équipes Customer Success et Applied AI de la région.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Lieu et déplacements&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Ce poste est basé à Paris, en France, avec des déplacements à prévoir pour rencontrer les partenaires et les clients.&lt;/p&gt;
&lt;h2&gt;&amp;nbsp;&lt;/h2&gt;
&lt;h2&gt;About the Role&lt;/h2&gt;
&lt;p&gt;This is a critical leadership role responsible for building and scaling Anthropic&#39;s consulting, GSIs and AI-native boutique partners in France.&lt;br&gt;You will be working closely with the sales team to make sure customers are adopting AI through our partners.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;This is a builder role, not a manager role.&lt;/strong&gt; Given Anthropic&#39;s stage, we need someone who has proven they can take partnerships from zero to scaled revenue engines — someone who has built these relationships from the ground up, not just inherited and managed existing ones.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Partnerships and execution:&amp;nbsp;&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;You will engage closely with the sales team to understand how partners can support customer Claude adoption&lt;/li&gt;
&lt;li&gt;You will guide partners in creating repeatable customer solutions that address specific use cases across industries including financial services, healthcare, retail, manufacturing, public sector, and professional services.&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;Performance and KPI ownership:&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Own and drive key performance indicators, partner-influenced revenue, partner delivery, consultants trained and certified&lt;/li&gt;
&lt;li&gt;Every deal influenced through your partner portfolio must be architected for customer success and long-term value expansion. You will establish success criteria for joint accounts, ensure proper implementation and adoption support, and create feedback loops that drive continuous improvement.&lt;/li&gt;
&lt;li&gt;Report on partnership health, progress, and commercial outcomes with data-driven insights&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Market Development &amp;amp; Brand Building&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Amplify the Anthropic brand in France strategic partner relationships&lt;/li&gt;
&lt;li&gt;Develop and execute market-specific GTM strategies adapted to local business practices and cultural nuances&lt;/li&gt;
&lt;li&gt;Navigate local regulatory, compliance, and data sovereignty considerations&lt;/li&gt;
&lt;li&gt;Create competitive differentiation through unique partner capabilities and joint value propositions&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;You may be a good fit if you have:&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Builder mentality — comfortable starting from zero and creating scaled partnerships&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;Fluent in English and French&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;8+ years of experience in enterprise technology partnerships, ideally within cloud, AI/ML, or platform businesses&lt;/li&gt;
&lt;li&gt;Data-driven mindset with focus on measurable outcomes and KPI attainment. Track record of driving incremental revenues through partnerships in the region&lt;/li&gt;
&lt;li&gt;History of delivering exceptional customer success and brand protection through partner channels&lt;/li&gt;
&lt;li&gt;Competitive drive — obsessed with winning and creating differentiation&lt;/li&gt;
&lt;li&gt;Collaborative approach with ability to work cross-functionally across sales, product, marketing, and regional teams&lt;/li&gt;
&lt;li&gt;Passion for AI and alignment with Anthropic&#39;s mission of beneficial AI development&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Working Relationships&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;You will formally report to the International Partnerships leader, while your day-to-day work will be led by our South EMEA Partnerships lead. You will also partner closely with Anthropic&#39;s regional sales leader and their Account Executives, as well as the in-region Customer Success and Applied AI teams.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Location and Travel&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;This role will be based in Paris, France with travel expected to engage with partners and customers externally.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The annual compensation range for this role is listed below.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;For sales roles, the range provided is the role’s On Target Earnings (&quot;OTE&quot;) range, meaning that the range includes both the sales commissions/sales bonuses target and annual base salary for the role.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Annual Salary:&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;€220.000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;€260.000 EUR&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h2&gt;&lt;strong&gt;Logistics&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;Minimum education: &lt;/strong&gt;Bachelor’s degree or an equivalent combination of education, training, and/or experience&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Required field of study:&amp;nbsp;&lt;/strong&gt;A field relevant to the role as demonstrated through coursework, training, or professional experience&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Minimum years of experience: &lt;/strong&gt;Years of experience required will correlate with the internal job level requirements for the position&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location-based hybrid policy:&lt;/strong&gt; Currently, we expect all staff to be in one of our offices at least 25% of the time. However, some roles may require more time in our offices.&lt;/p&gt;
&lt;p&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Visa sponsorship:&lt;/strong&gt;&amp;nbsp;We do sponsor visas! However, we aren&#39;t able to successfully sponsor visas for every role and every candidate. But if we make you an offer, we will make every reasonable effort to get you a visa, and we retain an immigration lawyer to help with this.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;For roles performing work in California: &lt;/strong&gt;We will consider for employment all qualified applicants, including those with arrest or conviction records or criminal histories, in a manner consistent with the requirements of applicable state and local laws, including the San Francisco Fair Chance Ordinance, the City of Los Angeles’ Fair Chance Initiative for Hiring Ordinance, the Los Angeles County Fair Chance Ordinance for Employers, and the California Fair Chance Act.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We encourage you to apply even if you do not believe you meet every single qualification.&lt;/strong&gt; Not all strong candidates will meet every single qualification as listed.&amp;nbsp; Research shows that people who identify as being from underrepresented groups are more prone to experiencing imposter syndrome and doubting the strength of their candidacy, so we urge you not to exclude yourself prematurely and to submit an application if you&#39;re interested in this work. We think AI systems like the ones we&#39;re building have enormous social and ethical implications. We think this makes representation even more important, and we strive to include a range of diverse perspectives on our team.&lt;br&gt;&lt;br&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Your safety matters to us.&lt;/strong&gt; To protect yourself from potential scams, remember that Anthropic recruiters only contact you ----- addresses. In some cases, we may partner with vetted recruiting agencies who will identify themselves as working on behalf of Anthropic. Be cautious of emails from other domains. Legitimate Anthropic recruiters will never ask for money, fees, or banking information before your first day. If you&#39;re ever unsure about a communication, don&#39;t click any links—visit&amp;nbsp;&lt;u data-stringify-type=&quot;underline&quot;&gt;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;http://anthropic.com/careers&quot; target=&quot;_blank&quot; data-stringify-link=&quot;http://anthropic.com/careers&quot; data-sk=&quot;tooltip_parent&quot; data-remove-tab-index=&quot;true&quot;&gt;anthropic.com/careers&lt;/a&gt;&lt;/u&gt;&amp;nbsp;directly for confirmed position openings.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;How we&#39;re different&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;We believe that the highest-impact AI research will be big science. At Anthropic we work as a single cohesive team on just a few large-scale research efforts. And we value impact — advancing our long-term goals of steerable, trustworthy AI — rather than work on smaller and more specific puzzles. We view AI research as an empirical science, which has as much in common with physics and biology as with traditional efforts in computer science. We&#39;re an extremely collaborative group, and we host frequent research discussions to ensure that we are pursuing the highest-impact work at any given time. As such, we greatly value communication skills.&lt;/p&gt;
&lt;p&gt;The easiest way to understand our research directions is to read our recent research. This research continues many of the directions our team worked on prior to Anthropic, including: GPT-3, Circuit-Based Interpretability, Multimodal Neurons, Scaling Laws, AI &amp;amp; Compute, Concrete Problems in AI Safety, and Learning from Human Preferences.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Come work with us!&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Anthropic is a public benefit corporation headquartered in San Francisco. We offer competitive compensation and benefits, optional equity donation matching, generous vacation and parental leave, flexible working hours, and a lovely office space in which to collaborate with colleagues. &lt;strong data-stringify-type=&quot;bold&quot;&gt;Guidance on Candidates&#39; AI Usage:&lt;/strong&gt;&amp;nbsp;Learn about&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.anthropic.com/candidate-ai-guidance&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.anthropic.com/candidate-ai-guidance&quot; data-sk=&quot;tooltip_parent&quot;&gt;our policy&lt;/a&gt; for using AI in our application process.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.fr">Jobs in France</a> on Arbeitnow</a>

&lt;h2&gt;&lt;strong&gt;In a nutshell&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;As a Business Analytics Intern at Picnic, you’ll be at the forefront of international innovation, tackling complex challenges with fresh, groundbreaking solutions. This dual-location role is all about driving impact. You&#39;ll analyze data, help identify opportunities, and support strategies that redefine the grocery shopping experience across Europe. Throughout this year-long program, you’ll exchange between two locations &lt;strong&gt;Paris (6 months) &lt;/strong&gt;and &lt;strong&gt;Amsterdam (6 months)&lt;/strong&gt;, gaining cross-market perspectives in a fast-paced environment.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Tricks of the trade&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Solving real-life puzzles: &lt;/strong&gt;Tackle critical business questions that shape Picnic’s business model every day.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Enabling: &lt;/strong&gt;Achieve operational excellence by approaching challenges with a data-driven and analytical mindset.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Building: &lt;/strong&gt;Create and optimize models for real-time improvements.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Communicating: &lt;/strong&gt;Work effectively with different teams to deliver impactful and sustainable solutions.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Owning your projects&lt;/strong&gt;: Take initiative by challenging the status-quo. Just because it’s been done that way doesn’t mean it’s the best way. Try us!&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Your superpowers&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;You are currently pursuing a &lt;strong&gt;Master’s&lt;/strong&gt; in a Quantitative field&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You have experience with &lt;strong&gt;SQL and Python&lt;/strong&gt; or similar programming languages&lt;/li&gt;
&lt;li&gt;You are able to hold fluent presentations both in &lt;strong&gt;English&lt;/strong&gt; and &lt;strong&gt;French&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;You have an&lt;strong&gt; EU citizenship&lt;/strong&gt;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You are available for &lt;strong&gt;12 months&lt;/strong&gt;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Depending on your Internship performance, we can discuss further opportunities for a full-time role at Picnic!&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Picnic Perks&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;💪Every expert was once a beginner!&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt; &lt;/strong&gt;You’ll get plenty of opportunities to challenge yourself and grow, including the Picnic Tech Academy, Lunch &amp;amp; Learn sessions, and tailored soft skills training. We also offer free professional weekly language courses.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🧑‍🎓Make a difference&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;You’ll work in an awesome scaleup environment with the freedom to drive your own projects and create a visible impact. Our fully electric vehicles and sustainable business model mean you’ll also be contributing to making the world a better place!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🎓Teamwork makes the dream work&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;With more than 80 nationalities across 3 countries, you’ll be part of a diverse company with plenty of cool stuff to get involved with, from board game evenings to after-work drinks to our company ski trip and more!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;📌Attractive package&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;We offer a gross salary of €1,500 per month in Paris and €800 per month in Amsterdam for a full-time internship.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Note&lt;/strong&gt;: You will need to &lt;strong&gt;secure your own housing&lt;/strong&gt; in both Amsterdam and Paris, though our team is happy to share local tips and guidance to help with your search!&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;<p>Find more <a href="https://www.arbeitnow.fr/english-speaking-jobs">English Speaking Jobs in France</a> on Arbeitnow</a>

&lt;p&gt;&lt;strong&gt;Mission Brief &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW87829766 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW87829766 BCX0&quot;&gt;As part of the Quality team, the primary purpose of the role is to manage quality control activities and to work with production team to &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87829766 BCX0&quot;&gt;maintain&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87829766 BCX0&quot;&gt; product quality by enforcing quality management policies, procedures and instructions and implement &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87829766 BCX0&quot;&gt;new approaches&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW87829766 BCX0&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW87829766 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Your Role in Our Space Mission:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Monitor the entire assembly, integration and testing cycle of launch vehicle (sub-) assemblies, plan and execute quality control activities, evaluate nonconformities, and specify corrective and preventive actions to solve the problems &lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conduct quality checks for ongoing works with site inspections on a regular basis and ensure that technical standards are always met&lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;39&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;
